from openpyxl import load_workbook
from collections import defaultdict
from pathlib import Path
src=Path('/root/Timesheet_Submissions.xlsx')
wb=load_workbook(src, data_only=False)
print('Workbook sheets:', wb.sheetnames)
ws=wb['Entries']
headers=[ws.cell(row=1,column=c).value for c in range(1, ws.max_column+1)]
print('\nEntries columns and observed Python dtypes:')
for idx,h in enumerate(headers, start=1):
    types=[]
    seen=set()
    for r in range(2, ws.max_row+1):
        v=ws.cell(r,idx).value
        t=type(v).__name__
        if t not in seen:
            seen.add(t); types.append(t)
    print(f'  {idx}. {h}: {", ".join(types)}')

br=wb['BreakRules']
print('\nBreakRules rows:')
br_headers=[br.cell(row=1,column=c).value for c in range(1, br.max_column+1)]
print(br_headers)
