    print([br.cell(r,c).value for c in range(1, br.max_column+1)])

# anomaly sample in target columns
col_map={h:i+1 for i,h in enumerate(headers)}
targets=['Hours Worked','Break Minutes','Approval Code']
print('\nEntries anomaly sample in Hours Worked / Break Minutes / Approval Code:')
count=0
for r in range(2, ws.max_row+1):
    row={h:ws.cell(r,col_map[h]).value for h in headers}
    reasons=[]
    for t in targets:
        v=row.get(t)
        if v is None:
            reasons.append(f'{t}=None/blank')
        elif isinstance(v,str):
            s=v
            if s.strip()=='' or s.strip().upper() in {'N/A','NA','NULL','NONE'}:
                reasons.append(f'{t}={v!r}')
            elif t in {'Hours Worked','Break Minutes'}:
                try: float(s)
                except Exception: reasons.append(f'{t}=non-numeric {v!r}')
        elif t in {'Hours Worked','Break Minutes'} and not isinstance(v,(int,float)):
            reasons.append(f'{t}=non-numeric type {type(v).__name__}')
    if reasons:
        count+=1
        print(f'  Excel row {r}: reasons={reasons}; values={[row.get(t) for t in targets]}; full_row={[row[h] for h in headers]}')
        if count>=20:
            break
print(f'Anomaly sample rows printed: {count}')
print(f'Entries dimensions: rows={ws.max_row-1}, columns={ws.max_column}')
